class Solution {
public:
    vector<int> longestRepeating(string s, string queryCharacters, vector<int>& queryIndices) {
        int n = s.size();
        struct Node {
            int len;
            int pref;
            int suff;
            int best;
            char lc;
            char rc;
        };
        int size = 1;
        while (size < n) size <<= 1;
        vector<Node> tree(2 * size);
        const Node EMPTY{0, 0, 0, 0, (char)0, (char)0};
        for (int i = 0; i < 2 * size; i++) tree[i] = EMPTY;
        for (int i = 0; i < n; i++) {
            tree[size + i] = {1, 1, 1, 1, s[i], s[i]};
        }
        auto merge = [&](Node& p, const Node& L, const Node& R) {
            if (L.len == 0) { p = R; return; }
            if (R.len == 0) { p = L; return; }
            p.len = L.len + R.len;
            p.lc = L.lc;
            p.rc = R.rc;
            p.pref = L.pref;
            if (L.pref == L.len && L.rc == R.lc) p.pref = L.len + R.pref;
            p.suff = R.suff;
            if (R.suff == R.len && L.rc == R.lc) p.suff = R.len + L.suff;
            p.best = max(L.best, R.best);
            if (L.rc == R.lc) p.best = max(p.best, L.suff + R.pref);
        };
        for (int i = size - 1; i >= 1; i--) merge(tree[i], tree[2 * i], tree[2 * i + 1]);

        vector<int> ans;
        ans.reserve(queryIndices.size());
        for (int q = 0; q < (int)queryCharacters.size(); q++) {
            int idx = queryIndices[q];
            char c = queryCharacters[q];
            int pos = size + idx;
            tree[pos] = {1, 1, 1, 1, c, c};
            pos >>= 1;
            while (pos >= 1) {
                merge(tree[pos], tree[2 * pos], tree[2 * pos + 1]);
                pos >>= 1;
            }
            ans.push_back(tree[1].best);
        }
        return ans;
    }
};
